" > /tmp/py_expected.txt && node -e "
import('fs').then(async (fs) => {
  const { bytesRepr } = await import('/output/pyrepr.mjs');
  const { execSync } = await import('child_process');
  // regenerate same sequences deterministically in JS via python itself is easier:
});
" 2>/dev/null; echo done

cd /tmp && python3 -c "
import random, json
random.seed(1234)
cases = []
# random byte strings
for _ in range(500):
    n = random.randint(0, 50)
    data = bytes(random.randrange(256) for _ in range(n))
    cases.append([data.hex(), repr(data)])
# targeted quote-heavy cases
for combo in ([39],[34],[39,34],[39,39,34],[34,39,39],[92,39],[39,92,34],[9,10,13,39],[0x7f,0x80,0xff,0x00]):
    data = bytes(combo)
    cases.append([data.hex(), repr(data)])
json.dump(cases, open('/tmp/cases.json','w'))
print(len(cases), 'cases written')
"
node -e "
const fs = require('fs');
(async () => {
  const { bytesRepr } = await import('/output/pyrepr.mjs');
  const cases = JSON.parse(fs.readFileSync('/tmp/cases.json', 'utf8'));
  let bad = 0;
  for (const [hex, expected] of cases) {
    const u8 = new Uint8Array(Buffer.from(hex, 'hex'));
    const got = bytesRepr(u8);
    if (got !== expected) {
      bad++;
      if (bad <= 5) console.log('MISMATCH', hex, 'got', JSON.stringify(got), 'want', JSON.stringify(expected));
    }
  }
  console.log(bad === 0 ? 'ALL ' + cases.length + ' CASES MATCH CPYTHON' : bad + ' mismatches');
})();
"
